if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_generate() {
    cat <<'EOF'
complete-bash	Generate completions for bash
complete-elvish	Generate completions for elvish
complete-fish	Generate completions for fish
complete-nushell	Generate completions for nushell
complete-powershell	Generate completions for powershell
complete-zsh	Generate completions for zsh
man	Generate manual page in roff format
man-markdown	Generate manual page in markdown format
EOF
}

_choice_interface() {
    if command -v ip >/dev/null 2>&1; then
        ip -o link show 2>/dev/null | gawk -F': ' '{ sub(/@.*/, "", $2); print $2 }'
        ip -o addr show 2>/dev/null | gawk '$3 == "inet" || $3 == "inet6" { sub(/\/.*/, "", $4); print $4 }'
    elif [[ -d /sys/class/net ]]; then
        find /sys/class/net -mindepth 1 -maxdepth 1 | sed 's|.*/||'
    elif command -v ifconfig >/dev/null 2>&1; then
        ifconfig -l 2>/dev/null | tr ' ' '\n'
    fi
}

_choice_verify() {
    cat <<'EOF'
no	Skip SSL verification
false	Skip SSL verification (alias for no)
yes	Verify SSL certificates (default)
true	Verify SSL certificates (alias for yes)
EOF
    _argc_util_comp_path
}
